SELECT 
  COUNT(DISTINCT event_id) AS total_fault_events
FROM gishub.fleet.fault_events;

SELECT 100.0 * COUNT(DISTINCT wc.event_id) / COUNT(DISTINCT fe.event_id) AS percentage_faults_with_warranty_claim
FROM gishub.fleet.fault_events fe
LEFT JOIN gishub.fleet.warranty_claims wc ON fe.event_id = wc.event_id;

SELECT 100.0 * COUNT(DISTINCT wc.event_id) / NULLIF(COUNT(DISTINCT fe.event_id), 0) AS percentage_faults_with_warranty_claim
FROM gishub.fleet.fault_events fe
LEFT JOIN gishub.fleet.warranty_claims wc ON fe.event_id = wc.event_id;
